/**
 * @param {number[]} nums
 * @return {number}
 */
var uniqueXorTriplets = function(nums) {
    const n = nums.length;
    const set = new Set();

    for (let i = 0; i < n; i++) {
        for (let j = i; j < n; j++) {
            for (let k = j; k < n; k++) {
                set.add(nums[i] ^ nums[j] ^ nums[k]);
            }
        }
    }

    return set.size;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var uniqueXorTriplets = function (nums) {
    const n = nums.length;

    if (n <= 2) {
        return n;
    }

    let ans = 1;

    while (ans <= n) {
        ans <<= 1;
    }

    return ans;
};
